"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[580],{4580:function(e,t,a){a.d(t,{Au:function(){return r},Mu:function(){return o},N5:function(){return i},No:function(){return u},Ot:function(){return n},n9:function(){return l},q:function(){return s},sg:function(){return c},t7:function(){return d}});let i={name:"Jordan Calhoun",initials:"JC",titleLine:"AI shipped with constraints and precision",tagline:"I ship AI with constraints and precision, so your business never has to worry about the back end again.",proofStats:[{n:"3",label:"live apps"},{n:"9+",label:"gated AI features"},{n:"1",label:"deliberately AI-free"}],location:"Remote (US)",availability:"Available immediately \xb7 Remote \xb7 US",email:"jordanmercalhoun@gmail.com",github:"https://github.com/flt-sudo",linkedin:"https://www.linkedin.com/in/jordanmercalhoun/",site:"https://flt-sudo.github.io",kicker:"Jordan Calhoun ships production LLM/AI features into real software — classification, vision extraction, grounded narration — with the containment and reliability discipline that keeps them safe in production.",aside:"I started building this kind of software to solve problems I kept running into as a founder. I haven't really stopped since."},n={ai:{label:"AI Integration",short:"AI",headline:"I ship LLM features into live products without breaking them.",summary:"I build real AI features — classification, vision extraction, grounded narration, AI-drafted messaging — and I make them safe to run in production: forced-tool structured output, sanitizers that treat model output as untrusted, an explicit fail-open/fail-loud policy, and containment enforced in CI so an AI route can never touch the database or escalate privilege."},se:{label:"Solutions Engineer",short:"SE",headline:"I build software that ships and gets used.",summary:"I work across the whole build, from figuring out what a team actually needs to getting it live in production. For one multi-branch franchise I built a role-based operations portal, took it live, and wrote the setup docs so their own staff could run it after I handed it off."},cs:{label:"Technical CS / Implementation",short:"CS",headline:"I get messy workflows live, then keep them running.",summary:"Setting up roles, getting people onboarded, writing the docs that non-technical staff can actually follow, and chasing down the things that break. I'm comfortable owning a customer from the first call through go-live and whatever comes after."},gtm:{label:"AI GTM / Demo & Growth",short:"GTM",headline:"I build the demo that closes, then the product behind it.",summary:"I can stand up a branded, working product demo for a prospect in an afternoon, because I built a reusable engine to do it. When a demo lands, I'm the one who takes it the rest of the way to production."},agency:{label:"Agency partner",short:"Agency",headline:"White-label portals, dashboards and field apps for agencies — fixed price, two to three weeks.",summary:"You sell the site and keep the client. When they ask for a login, a client portal, a job tracker, a field app — or hand you an AI-built prototype that isn't safe to ship — I build or harden that piece under your name, at a fixed price, and hand it back production-grade: audited per role, Row-Level Security verified, screenshot guide and handoff PDF included.",meta:"White-label \xb7 fixed price \xb7 2–3 weeks \xb7 US, remote",ctas:{primary:{label:"Book 15 minutes",href:"mailto:jordanmercalhoun@gmail.com?subject=15%20min%20%E2%80%94%20white-label%20build"},secondary:{label:"See a live build ↗",href:"https://trueline-hvac-demo.vercel.app",external:!0},tertiary:{label:"What I build",href:"#projects"}},contact:{h2:"You keep the client. I build the part you'd otherwise turn away.",body:"Terms in one breath: half to start, balance at handoff. The work assigns to your agency on final payment. I don't solicit your clients. Net-15. Fixed scope in writing before money moves; anything outside it is a flat change order.",ctaLabel:"Book 15 minutes",pricing:["Portals & dashboards from $7k wholesale","AI-prototype hardening from $2.5k \xb7 48-hour audit first","Care & hosting from $200 / mo"],hideResumes:!0}}},o=["ai","se","cs","gtm","agency"],r=[{title:"Production AI / LLM Integration",items:["Ships production LLM features (classification, vision extraction, grounded narration)","Forced-tool structured output + schema validation","AI containment enforced in CI (no DB access, no privilege escalation)","Fail-open vs fail-loud degradation policy","Model-cost routing (Haiku / Sonnet / Opus)","TCPA-safe AI-drafted messaging"]},{title:"Product & Workflow",items:["Process-to-software design","RBAC & multi-tenancy","Lead → job pipelines","Onboarding & invite flows","Document / PDF generation","Dashboards & reporting"]},{title:"Full-Stack",items:["TypeScript","React","Next.js (App Router)","Node.js","Tailwind","Postgres schema design"]},{title:"Backend & Data",items:["Supabase (Postgres / Auth / Edge Functions)","Row-Level Security","Migrations","Service-role patterns"]},{title:"Integrations & Automation",items:["Stripe (payment links, webhooks)","Twilio SMS (consent / quiet-hours / audit)","Resend email","Capacitor / iOS","GitHub Actions CI","Vercel"]},{title:"GTM & Solutions",items:["Branded demo builds","One-command client scaffolding","Instrumented funnels","Proposal & pricing scaffolding","Technical onboarding"]},{title:"Security & Compliance",muted:!0,items:["Postgres RLS & privilege-escalation guards","TCPA-compliant messaging","Auth-gated, contained AI routes"]}],s=[{id:"airmarshalls",name:"Air Marshalls — Operations Portal",kicker:"A role-based operations portal that a multi-branch franchise runs in production.",status:"Live \xb7 Production",problem:"A multi-branch field-services franchise was running intake, jobs, and chain-of-custody on scattered tools with no role-based control.",metrics:["Live in production at airmarshallscorporate.com","4-tier role hierarchy enforced in Postgres Row-Level Security","Read-only AI copilot with no database access by design","HEIC → JPEG photo-stamping pipeline for field evidence"],build:["Shipped a live multi-tenant portal with a 4-tier role hierarchy (HQ → regional → branch manager → technician) enforced in Postgres Row-Level Security.","Built a public lead intake → job-conversion pipeline (validated form, branch routing, status tracking).","Implemented digital chain-of-custody forms with signature capture and collision-resistant document numbers, behind Edge Functions for invite/role/password management, a privilege-escalation guard, RLS/acceptance tests, and CI — wrapped in a Capacitor iOS shell.","Added an AI assist tier a human always finalizes: an intake QA bot runs ~10 deterministic checks (missing or duplicate Sample IDs, blank locations, a missing outdoor control) before samples reach the lab, and an AI report drafter produces the six-section assessment for a credentialed reviewer to edit, e-sign, and export as a branded, court-ready PDF.","Shipped a read-only in-app copilot that explains the current screen and deep-links staff to a record by number — no database access by design."],outcome:"The chain-of-custody is the legal deliverable — one wrong Sample ID or a missing outdoor control compromises the lab work. Now every COC is machine-checked for entry errors before it reaches the lab, every report leaves the portal as a human-signed PDF, and a non-technical operator can stand the whole system up from my setup guide in under an hour.",tech:["Next.js 14","React","Supabase","Postgres RLS","Edge Functions","Anthropic AI","Vercel","Capacitor/iOS","GitHub Actions"],tags:["RBAC","Multi-tenant","Live","Lead pipeline","AI assist"],links:{live:{label:"Visit live site",url:"https://airmarshallscorporate.com"}},priority:{ai:1,se:1,cs:1,gtm:3,agency:1}},{id:"trueline",name:"Trueline HVAC — Branded Demo Portal",kicker:"A fictional HVAC company's site + ops portal, stood up from the delivery engine — the walk-through I send agencies.",status:"Live \xb7 Demo",problem:"Agencies need to see the finished thing, not a slide. Trueline is a made-up HVAC company with a real, working build behind it — the same engine that runs the production portals, wearing a demo brand.",metrics:["Live at trueline-hvac-demo.vercel.app — demo login on request","Fictional company; every name and number is invented for the demo","Quotes, jobs and maintenance flows on the same role-based portal engine","Branded and deployed from the delivery engine, not built from scratch"],build:["Scaffolded a branded marketing site and role-based ops portal from the delivery engine, then themed it as a fictional HVAC shop.","Wired the engine's quotes and maintenance-scheduling features so an agency owner can click through a real workflow, not a mockup.","Kept it deliberately fictional after learning the hard way that a demo brand must never collide with a real company's name."],outcome:"This is what I show on the first call. Any agency client's version starts here — new brand, their roles, their fields — and ships in two to three weeks.",tech:["Next.js 14","Supabase","Postgres RLS","Vercel"],tags:["Demo","White-label","Portal engine"],links:{live:{label:"Open the demo",url:"https://trueline-hvac-demo.vercel.app"}},priority:{ai:9,se:9,cs:9,gtm:9,agency:1}},{id:"brightwater",name:"Brightwater — Repeatable Client Demo",kicker:"A branded site + role-based portal scaffolded from a reusable engine in one command.",status:"Public code",problem:"Show that a productized 'website + internal portal + lead pipeline' can be stood up for any small business — fast and repeatably.",build:["Scaffolded a complete client (marketing site, portal, database schema, 4-tier roles) from one command + a reusable engine, then deployed it against a seeded multi-location database.","Demonstrates the core motion: a customer submits a request on the public site → it lands in the staff inbox → one click converts it to a technician-assigned job.","Branch-level access enforced at the database layer with Row-Level Security."],outcome:"Once the engine existed, onboarding a new client was mostly new branding and a deploy. That's the whole point of it.",tech:["Next.js","React","Supabase","Postgres RLS","Vercel"],tags:["Demo","GTM","RBAC","Repeatable"],links:{code:{label:"View code",url:"https://github.com/flt-sudo/brightwater-portal"},loom:!0},priority:{ai:9,se:2,cs:3,gtm:1,agency:2}},{id:"engine",name:"Delivery Engine (site-portal-starter)",kicker:"A productized SaaS delivery system deployed per client as a single app.",status:"Engine",problem:"Bespoke client builds don't scale for a solo operator — every project starts from scratch.",build:["Built a reusable 'marketing site + internal portal + lead pipeline' engine — one codebase, one deploy per client.","Wrote a zero-dependency `new-client` scaffolder that spins up a branded demo branch, patches brand config, and generates proposal + research docs in one command.","Documented and ran a full GTM motion: qualify → research → priced proposal → branded demo → ship."],outcome:"It's how I avoid starting from scratch every time, while keeping each client's build inside guardrails I can support.",tech:["Next.js","Supabase","Node","Vercel"],tags:["Productized","GTM","Tooling"],links:{},priority:{ai:9,se:2,cs:2,gtm:1,agency:1}},{id:"flytline",name:"Flytline — Scheduling & Recovery SaaS",kicker:"Multi-tenant SaaS that auto-recovers cancelled bookings via a matching engine.",status:"MVP",problem:"When a scheduled booking cancels, the slot and revenue are usually lost with no system to fill it.",metrics:["12-table multi-tenant schema, ~37 Row-Level Security policies across 4 roles","TCPA-gated SMS: consent, quiet-hours, rate-limit, and STOP handling","5 AI features, each failing safe to its non-AI path","Deterministic matcher + consent gates kept as the sole source of truth"],build:["Built automatic cancellation recovery via a rules-and-scoring matching engine with hard eligibility filters, soft preference scoring, and timed retry windows.","Designed a 12-table multi-tenant schema with ~37 Row-Level Security policies across 4 roles, plus a service-role-only write path for the match/recovery tables.","Implemented TCPA-compliant SMS automation (consent, quiet-hours, rate-limit, full audit trail) and operator dashboards quantifying business impact.","Added a server-only, auth-gated AI layer over the recovery loop — roster import from CSV/PDF/screenshot, offer personalization, intake classification, plain-English match rationales, and a stats narrator — kept strictly additive: the deterministic matcher and the TCPA consent gates stay the sole source of truth, AI drafts while a human finalizes, and each feature fails safe to its non-AI path."],outcome:"It turns cancellations that used to be lost revenue into rebooked slots, and it follows the SMS consent rules while doing it. The AI is an assist over the deterministic core, not a replacement for it.",tech:["Next.js 16","TypeScript","Supabase","Twilio","Anthropic AI","Postgres RLS"],tags:["Automation","Multi-tenant","Compliance","AI assist"],links:{live:{label:"Try the live demo",url:"https://tryflytline.com/demo/public"}},priority:{ai:2,se:3,cs:2,gtm:3,agency:3}},{id:"markwatch",name:"MarkWatch — Growth Wedge",kicker:"A live free-tool wedge with an instrumented conversion funnel.",status:"Live wedge",problem:"Validate demand for a paid monitoring product before building the monitoring engine.",build:["Shipped a live free deadline-calculator designed to convert into a paid product.","Built an instrumented conversion funnel — event tracking and lookup → signup capture — behind a disciplined demand-test gate."],outcome:"I wanted to see whether anyone would actually convert before I built the expensive part.",tech:["Next.js","React","Supabase","Analytics"],tags:["GTM","Funnel","Growth"],links:{},priority:{ai:9,se:9,cs:9,gtm:2,agency:9}},{id:"plugready",name:"PlugReady — Compliance SaaS",kicker:"Regulated compliance-training platform with certificates and audit trails.",status:"Case study",problem:"A regulated retail vertical needs verifiable proof of employee compliance training.",build:["Built server-side PDF certificate generation, QR-code verification, and Stripe webhooks.","Multi-tenant data isolated with Row-Level Security; auth, dashboards, and training flows end-to-end."],outcome:"It replaces a paper training-record process with something a shop owner can pull up and show an inspector.",tech:["Next.js","Supabase","Stripe","PDF generation","Postgres RLS"],tags:["Payments","Compliance","PDF"],links:{},priority:{ai:9,se:3,cs:2,gtm:3,agency:3}},{id:"mosaic",name:"MOSAIC Eligible — Lookup Engine",kicker:"A deterministic eligibility-verdict engine with SEO pages and Stripe checkout.",status:"Case study",problem:"No canonical per-item answer existed for a niche regulatory eligibility question.",build:["Built a deterministic verdict engine over a structured catalog with fuzzy search and liability-aware 'verify' states.","SEO-indexed static pages for organic discovery; Stripe payment link for the paid tier."],outcome:"A free lookup that answers the one question people search for, with a paid tier for the full catalog.",tech:["Next.js 15","React 19","TypeScript","Stripe","SEO/SSG"],tags:["SEO","Payments","Product"],links:{},priority:{ai:9,se:9,cs:9,gtm:9,agency:9}},{id:"cachelens",name:"CacheLens — LLM Cost Tooling",kicker:"Static analyzer that flags LLM prompt-cache-defeating patterns by dollar cost.",status:"Case study",problem:"Teams ship prompt code that silently defeats provider prompt-caching and inflates spend.",build:["Built a TypeScript parser + detectors that catch cache-defeating patterns and attribute them to estimated dollar cost.","Backed by a test suite; scans hundreds of files in milliseconds."],outcome:"I built it because I kept watching prompt code quietly run up cache costs that nobody was catching.",tech:["TypeScript","Static analysis","CLI"],tags:["AI / LLM","Tooling","Cost"],links:{},priority:{ai:3,se:9,cs:9,gtm:3,agency:9}}],l=["Ships production LLM features (classification, vision, narration)","AI containment enforced in CI — no DB access, no privilege escalation","Forced-tool structured output with untrusted-model sanitizers","Read-only AI copilot, enum-constrained by role","Live multi-tenant portals in production","Row-Level Security on every table","Compliance-aware (TCPA) AI-drafted messaging","Stripe \xb7 Twilio \xb7 PDF \xb7 QR integrations"],c={agency:["Live multi-tenant portals in production","Row-Level Security on every table","Per-role audit + screenshot handoff guide on every build","Fixed price, fixed scope — change orders flat","AI features gated and contained — never touch the database","Stripe \xb7 Twilio \xb7 PDF \xb7 QR integrations"]},d={title:"Security foundations",blurb:"A self-directed security portfolio that explains why my SaaS work is built rigorously: Python SOC/IR tooling, SIEM detection rules, and incident-response playbooks mapped to NIST 800-61, MITRE ATT&CK, and CIS benchmarks. Presented as learning work — Google Cybersecurity and Security+ in progress, not professional SOC experience.",link:{label:"View code",url:"https://github.com/flt-sudo/engineering-portfolio"},tags:["NIST CSF","MITRE ATT&CK","CIS","Incident Response","Python"]},u=[{label:"Master r\xe9sum\xe9",file:"jordan-calhoun-resume.pdf",lens:"master"},{label:"Solutions / GTM cut",file:"jordan-calhoun-resume-GTM.pdf",lens:"gtm"},{label:"Technical CS cut",file:"jordan-calhoun-resume-TechnicalCS.pdf",lens:"cs"}]}}]);